package com.lyqentra.pulso;

import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import androidx.annotation.Nullable;

public class PulsoPlaybackService extends Service {
  public static final String ACTION_PLAY="com.lyqentra.pulso.PLAY", ACTION_PAUSE="com.lyqentra.pulso.PAUSE", ACTION_TOGGLE="com.lyqentra.pulso.TOGGLE", ACTION_NEXT="com.lyqentra.pulso.NEXT", ACTION_PREVIOUS="com.lyqentra.pulso.PREVIOUS", ACTION_SEEK="com.lyqentra.pulso.SEEK", ACTION_STOP="com.lyqentra.pulso.STOP";
  private static final String CHANNEL="pulso_playback";
  public static volatile PulsoPlaybackService instance; public static volatile int currentPosition=0, currentDuration=0; public static volatile boolean playing=false; private static volatile int[] savedEq={0,0,0,0,0};
  private MediaPlayer player; private MediaSession mediaSession; private android.media.audiofx.Equalizer equalizer; private String title="PULSO", artist="Reproduciendo música", uri=""; private int duration=0; private final Handler handler=new Handler(Looper.getMainLooper()); private final Runnable ticker=new Runnable(){public void run(){updateState();if(player!=null&&player.isPlaying())handler.postDelayed(this,500);}};
  @Override public void onCreate(){ super.onCreate(); instance=this; createChannel(); mediaSession=new MediaSession(this,"PULSO"); mediaSession.setCallback(new MediaSession.Callback(){
    @Override public void onPlay(){ resume(); }
    @Override public void onPause(){ pause(); }
    @Override public void onStop(){ stopPlayback(); }
    @Override public void onSeekTo(long pos){ seek((int)pos); }
    @Override public void onSkipToNext(){ sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_NEXT")); }
    @Override public void onSkipToPrevious(){ sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_PREVIOUS")); }
  }); mediaSession.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS | MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS); mediaSession.setActive(false); }
  private void createChannel(){ if(Build.VERSION.SDK_INT>=26){ NotificationChannel c=new NotificationChannel(CHANNEL,"Reproducción de PULSO",NotificationManager.IMPORTANCE_LOW); c.setDescription("Controles de reproducción de música"); ((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c); } }
  @Override public int onStartCommand(Intent intent,int flags,int startId){ if(intent==null)return START_STICKY; String a=intent.getAction(); if(ACTION_NEXT.equals(a)){sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_NEXT"));} else if(ACTION_PREVIOUS.equals(a)){sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_PREVIOUS"));} else if(ACTION_PLAY.equals(a)){ uri=intent.getStringExtra("uri"); title=intent.getStringExtra("title"); artist=intent.getStringExtra("artist"); startTrack(); } else if(ACTION_PAUSE.equals(a)) pause(); else if(ACTION_TOGGLE.equals(a)){ if(player!=null&&player.isPlaying())pause();else resume(); } else if(ACTION_SEEK.equals(a))seek(intent.getIntExtra("position",0)); else if(ACTION_STOP.equals(a))stopPlayback(); updateNotification(); return START_STICKY; }
  private void startTrack(){ try{ mediaSession.setActive(true); if(player!=null){player.release();player=null;} player=new MediaPlayer(); player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()); player.setDataSource(this,Uri.parse(uri)); player.setOnPreparedListener(mp->{duration=mp.getDuration(); currentDuration=duration; try { if(equalizer!=null)equalizer.release(); equalizer=new android.media.audiofx.Equalizer(0,mp.getAudioSessionId()); equalizer.setEnabled(true); applyEqualizer(savedEq); } catch(Exception ignored) {} playing=true; mp.start();handler.removeCallbacks(ticker);handler.post(ticker); updateState(); updateNotification();}); player.setOnCompletionListener(mp->{updateState();sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_ENDED"));}); player.setOnErrorListener((mp,w,e)->{sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_ERROR"));return true;}); startForeground(71,buildNotification()); player.prepareAsync(); }catch(Exception e){stopForeground(true);sendBroadcast(new Intent("com.lyqentra.pulso.NATIVE_ERROR"));} }
  private void resume(){ if(player!=null){try{mediaSession.setActive(true);player.start();playing=true;}catch(Exception ignored){} updateState();updateNotification();} }
  private void pause(){ if(player!=null&&player.isPlaying())player.pause();playing=false;updateState();updateNotification(); }
  private void seek(int ms){if(player!=null)try{player.seekTo(Math.max(0,Math.min(ms,player.getDuration())));currentPosition=ms;}catch(Exception ignored){}updateState();}
  private void stopPlayback(){playing=false;currentPosition=0;currentDuration=0;if(player!=null){player.stop();player.release();player=null;} mediaSession.setActive(false);stopForeground(true);stopSelf();}
  private void updateState(){ if(mediaSession!=null){ mediaSession.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title==null?"PULSO":title).putString(MediaMetadata.METADATA_KEY_ARTIST,artist==null?"":artist).putLong(MediaMetadata.METADATA_KEY_DURATION,currentDuration).build()); } if(player!=null)try{currentPosition=player.getCurrentPosition();}catch(Exception ignored){} if(mediaSession==null)return; PlaybackState state=new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_STOP).setState(player!=null&&player.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,player==null?0:player.getCurrentPosition(),player!=null&&player.isPlaying()?1f:0f).build();mediaSession.setPlaybackState(state); }
  private Notification buildNotification(){ Intent open=getPackageManager().getLaunchIntentForPackage(getPackageName()); PendingIntent content=PendingIntent.getActivity(this,1,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); PendingIntent prev=action(ACTION_PREVIOUS,2), toggle=action(ACTION_TOGGLE,3), next=action(ACTION_NEXT,4); Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this); return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(title==null?"PULSO":title).setContentText(artist==null?"":artist).setContentIntent(content).setVisibility(Notification.VISIBILITY_PUBLIC).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"Anterior",prev).build()).addAction(new Notification.Action.Builder(player!=null&&player.isPlaying()?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,player!=null&&player.isPlaying()?"Pausar":"Reproducir",toggle).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"Siguiente",next).build()).setStyle(new Notification.MediaStyle().setMediaSession(mediaSession.getSessionToken()).setShowActionsInCompactView(0,1,2)).setOngoing(player!=null&&player.isPlaying()).build(); }
  private PendingIntent action(String action,int id){Intent i=new Intent(this,PulsoPlaybackService.class).setAction(action);return PendingIntent.getService(this,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
  private void updateNotification(){if(mediaSession!=null && (player!=null || playing)) mediaSession.setActive(true);updateState();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(71,buildNotification());}
  @Override public void onTaskRemoved(Intent rootIntent){ if(player!=null&&player.isPlaying())startForeground(71,buildNotification()); }
  @Override public void onDestroy(){if(player!=null)player.release();if(equalizer!=null)equalizer.release();instance=null;if(mediaSession!=null)mediaSession.release();super.onDestroy();}
  public static void setEqualizerBands(int[] values) { if(values!=null)savedEq=values.clone(); if(instance!=null)instance.applyEqualizer(savedEq); }
  private void applyEqualizer(int[] values) { try { if(equalizer==null)return; short count=equalizer.getNumberOfBands(); for(int i=0;i<Math.min(values.length,count);i++){ short band=(short)Math.round(i*(count-1)/Math.max(1.0,(double)(values.length-1))); short range[]=equalizer.getBandLevelRange(); int level=Math.max(range[0],Math.min(range[1],values[i]*100)); equalizer.setBandLevel(band,(short)level); } } catch(Exception ignored){} }
  @Nullable @Override public IBinder onBind(Intent intent){return null;}
}
